mapper.update:
UPDATE runs
SET gateway_run_id = #{gatewayRunId}
WHERE id = #{id}

mapper.select:
SELECT r.id AS run_id, r.session_id AS session_id, r.turn_id AS turn_id, r.request_id AS request_id, r.model_id AS model_id, r.status AS status, r.error_code AS error_code, r.error_message AS error_message, r.tokens_in AS tokens_in, r.tokens_out AS tokens_out, r.cache_read_tokens AS cache_read_tokens, r.cache_write_tokens AS cache_write_tokens, r.started_at AS started_at, r.settled_at AS settled_at, s.user_id AS user_id, u.email AS email FROM runs r JOIN sessions s ON s.id = r.session_id JOIN users u ON u.id = s.user_id
WHERE r.request_id = #{requestId} WHERE r.turn_id = #{turnId} WHERE r.id = #{runId}
ORDER BY r.started_at DESC LIMIT 1
